<?php $home=null;foreach($site_settings as $block)if($block['slug']==='home'){$home=$block;break;} ?><section class="cms-hero"><p>FERRETERÍA AYALA</p><h1><?= e($home['title']??'Ferretería Ayala') ?></h1><?php if($home):?><p class="cms-prose"><?= e($home['body']) ?></p><?php endif?><a class="admin-primary-button" href="/solicitar-cotizacion">Solicitar cotización</a></section>
<form class="cms-select" method="get"><label for="cms-branch">Información de sucursal</label><select id="cms-branch" name="branch_id"><option value="">Información general</option><?php foreach($branches as $b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select><button class="admin-secondary-button">Consultar</button></form>
<?php foreach(['banners'=>'Destacados','promotions'=>'Promociones publicitarias','events'=>'Eventos','reviews'=>'Testimonios'] as $kind=>$heading):if(!$$kind)continue;?><section class="cms-section"><h2><?= e($heading) ?></h2><div class="cms-grid"><?php component('cms-cards',['cards'=>$$kind,'kind'=>$kind]);?></div></section><?php endforeach?>
<?php $institutional=array_values(array_filter($site_settings,static fn($r)=>$r['slug']!=='home'));if($institutional):?><section class="cms-section"><h2>Acerca de nosotros</h2><div class="cms-grid"><?php component('cms-cards',['cards'=>$institutional,'kind'=>'site_settings']);?></div></section><?php endif?>
<section class="cms-section"><h2>Sucursales</h2><?php if(!$branches):?><p>La información de sucursales todavía no está publicada.</p><?php else:?><div class="cms-grid"><?php foreach($branches as $b):?><article class="cms-card"><div><h3><?= e($b['name']) ?></h3><?php foreach(['address','phone','email'] as $k):if($b[$k]!==null&&$b[$k]!==''):?><p><?= e($b[$k]) ?></p><?php endif;endforeach?><?php if($b['latitude']!==null):?><p>Coordenadas: <?= e($b['latitude']) ?>, <?= e($b['longitude']) ?></p><?php endif?></div></article><?php endforeach?></div><?php endif?></section>

<?php $points=array_values(array_filter($branches,static fn($b)=>$b['latitude']!==null&&$b['longitude']!==null));if($points):$lats=array_column($points,'latitude');$lons=array_column($points,'longitude');$minLat=(float)min($lats);$maxLat=(float)max($lats);$minLon=(float)min($lons);$maxLon=(float)max($lons);$spanLat=max(.01,$maxLat-$minLat);$spanLon=max(.01,$maxLon-$minLon);?><section class="cms-section"><h2>Mapa de sucursales</h2><figure><svg class="cms-coordinate-map" viewBox="0 0 800 400" role="img" aria-label="Mapa de ubicación relativa por coordenadas de las sucursales"><rect width="800" height="400" rx="12" fill="#f3f3f3"/><path d="M40 200H760M400 40V360" stroke="#bbb" stroke-dasharray="6 6"/><?php foreach($points as $i=>$b):$x=$maxLon===$minLon?400:80+640*((float)$b['longitude']-$minLon)/$spanLon;$y=$maxLat===$minLat?200:320-240*((float)$b['latitude']-$minLat)/$spanLat;?><circle cx="<?= e($x) ?>" cy="<?= e($y) ?>" r="12" fill="#f58220"><title><?= e($b['name'].' · '.$b['latitude'].', '.$b['longitude']) ?></title></circle><text x="<?= e($x) ?>" y="<?= e($y-20) ?>" text-anchor="middle" font-size="18"><?= e($i+1) ?></text><?php endforeach?></svg><figcaption><ol class="cms-map-legend"><?php foreach($points as $b):?><li><?= e($b['name']) ?>: <?= e($b['latitude']) ?>, <?= e($b['longitude']) ?></li><?php endforeach?></ol><p>Las posiciones representan las coordenadas registradas de cada sucursal.</p></figcaption></figure></section><?php endif?>
